import heapq


def _interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None
        for subset in combinations(jobs, k):
            ids = tuple(sorted(job["id"] for job in subset))
            idset = set(ids)
            if idset & blocked or not mandatory.issubset(idset):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not lo <= counts.get(group, 0) <= hi
                   for group, (lo, hi) in quotas.items()):
                continue
            events = []
            for job in subset:
                events.append((job["start"], 1))
                events.append((job["end"], -1))
            active = 0
            valid = True
            for _, delta in sorted(events):  # end (-1) precedes start (+1)
                active += delta
                if active > capacity:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and
                     (ids > best_ids if tie == "largest" else ids < best_ids))):
                best_value, best_ids = value, ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _build_component_06():
    def rounded(n, d, mode):
        if mode == "half_up":
            return (2 * n + d) // (2 * d)
        return n // d

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for pos, event in enumerate(data["events"]):
            seq = event.get("sequence", 0)
            if seq > cutoff:
                continue
            eid = event.get("id", "anonymous:" + str(pos))
            key = (seq, event.get("revision", 0), pos)
            if eid not in winners or key > winners[eid][0]:
                winners[eid] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(raw * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = (event.get("account", "default") + "|" +
                   event.get("currency", "USD"))
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        candidates = {}
        for name in packages:
            allowed = []
            for row in packages[name]:
                v = row["version"]
                if v in blocked.get(name, []) or (name in pins and pins[name] != v):
                    continue
                allowed.append(row)
            candidates[name] = allowed

        best_vector = None
        best_versions = None
        # Assign each name either absent or one permitted row; at most 4^6 cases.
        choices = [(None, *candidates[name]) for name in packages]
        ordered_names = list(packages)
        def search(i, assignment):
            nonlocal best_vector, best_versions
            if i < len(ordered_names):
                name = ordered_names[i]
                for row in choices[i]:
                    assignment[name] = row
                    search(i + 1, assignment)
                assignment.pop(name, None)
                return

            installed = {name for name, row in assignment.items() if row is not None}
            for name, (lo, hi) in roots.items():
                row = assignment[name]
                if row is None or not lo <= row["version"] <= hi:
                    return

            edges = {}
            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                row = assignment[name]
                if row is None:
                    return
                deps = []
                for dep in row.get("deps", []):
                    feature = dep.get("feature")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    other_row = assignment[other]
                    if (other_row is None or
                            not dep["min"] <= other_row["version"] <= dep["max"]):
                        return
                    deps.append(other)
                    stack.append(other)
                edges[name] = deps
            if installed != reachable:
                return

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True
            if any(not visit(name) for name in reachable):
                return

            vector = tuple(assignment[name]["version"] if assignment[name] is not None
                           else -1 for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {name: assignment[name]["version"]
                                 for name in installed}

        search(0, {})
        if best_vector is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source = data["source"]
        initial_mask = bit_for.get(source, 0)
        coupons = data["coupons"]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_state = (source, initial_mask, 0)
        dist = {start_state: data["start"]}
        queue = [(data["start"], source, initial_mask, 0)]
        while queue:
            time, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if dist.get(state) != time:
                continue
            if node == data["target"] and mask == full and used == coupons:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < coupons:
                    duration = max(1, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, used + 1))
                for duration, next_used in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = edge["v"]
                    next_mask = mask | bit_for.get(nxt, 0)
                    next_state = (nxt, next_mask, next_used)
                    if arrival < dist.get(next_state, float("inf")):
                        dist[next_state] = arrival
                        heapq.heappush(queue, (arrival, nxt, next_mask, next_used))
        return {"arrival": None}
    return solve


